/// <summary>
/// Static access to Exoforge services matching the extension runtime syntax.
/// In Unity, uses the ambient ExoforgeSDK.Client; in standalone applications, assign ExoServices.Client.
/// </summary>
public static class ExoServices
{
    private static Func<ExoClient>? _clientLocator;
    private static ExoClient? _fallbackClient;

    /// <summary>The active ExoClient used by static service calls.</summary>
    public static ExoClient Client
    {
        get
        {
            if (_clientLocator != null) return _clientLocator();
            if (_fallbackClient != null) return _fallbackClient;

            var unitySdkType = Type.GetType("Exoforge.Client.Unity.ExoforgeSDK, Exoforge.SDK")
                ?? Type.GetType("Exoforge.Client.Unity.ExoforgeSDK, Exoforge.SDK.Runtime")
                ?? Type.GetType("Exoforge.Client.Unity.ExoforgeSDK");

            if (unitySdkType == null)
            {
                try
                {
                    foreach (var asm in AppDomain.CurrentDomain.GetAssemblies())
                    {
                        unitySdkType = asm.GetType("Exoforge.Client.Unity.ExoforgeSDK");
                        if (unitySdkType != null) break;
                    }
                }
                catch { }
            }

            if (unitySdkType != null)
            {
                var prop = unitySdkType.GetProperty("Client", BindingFlags.Public | BindingFlags.Static);
                if (prop?.GetValue(null) is ExoClient unityClient)
                {
                    return unityClient;
                }
            }

            throw new InvalidOperationException("No active ExoClient configured. Call ExoforgeSDK.Auth.LoginAnonymously(), ExoforgeSDK.ConnectAsync() or assign ExoServices.Client.");
        }
        set => _fallbackClient = value;
    }

    /// <summary>Configures a custom resolver for the active ExoClient.</summary>
    public static void SetClientLocator(Func<ExoClient> locator) => _clientLocator = locator;

    /// <summary>Access the Achievements service contract.</summary>
